package irvine.oeis.a401;

import irvine.math.predicate.Predicates;
import irvine.math.z.Integers;
import irvine.math.z.Z;

/**
 * A401043 Total Betti number of K[x_1,...,x_r]/I_n over K[x_1,...,x_r], where r = pi(n) and I_n is generated by the monomials x_1^e_1*...*x_r^e_r with prime(1)^e_1*...*prime(r)^e_r &gt; n.
 * @author Sean A. Irvine
 */
public class A401043 extends A401042 {

  private long mN = 1;
  private long mPi = 0;

  @Override
  public Z next() {
    if (Predicates.PRIME.is(++mN)) {
      ++mPi;
    }
    return Integers.SINGLETON.sum(0, mPi, k -> t(mN, k));
  }
}
